<?php
namespace App\Http\Controllers\Api\V1;
use App\Enums\UserRole; use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\{JsonResponse,Request}; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\Rules\Password;
class AuthController extends Controller { public function register(Request $r):JsonResponse{$data=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|unique:users','phone'=>'nullable|string|max:30|unique:users','password'=>['required','confirmed',Password::min(10)->letters()->numbers()],'role'=>'required|in:customer,technician']);$user=User::create($data);return response()->json(['data'=>$user,'token'=>$user->createToken('fixifier-web')->plainTextToken],201);} public function login(Request $r):JsonResponse{$data=$r->validate(['email'=>'required|email','password'=>'required']);$user=User::where('email',$data['email'])->first();abort_unless($user&&Hash::check($data['password'],$user->password),422,'Invalid credentials.');$user->tokens()->delete();return response()->json(['data'=>$user,'token'=>$user->createToken('fixifier-web')->plainTextToken]);} public function logout(Request $r):JsonResponse{$r->user()->currentAccessToken()->delete();return response()->json(['message'=>'Logged out.']);} }
